# I see the error - get_robot_position is not a native primitive, it's an original function that needs to be called via submit_capx_action
# Let me first check what APIs are available and understand the scene better

result = primitives.call(name='get_capx_available_apis')
if result.ok:
    print(f"Available APIs: {result.output}")
else:
    print(f"Failed to get APIs: {result}")

# Let me observe the scene to understand what objects are present
result = primitives.call(name='observe_capx_scene', query="What objects are visible in the scene?")
if result.ok:
    print(f"Scene observation: {result.output}")
else:
    print(f"Failed to observe scene: {result}")

# Good! The find_object_base_rotate succeeded. Now I can see the red toolbox on a shelf and there's a black tool (looks like a screwdriver or similar) next to it.

# Let me now try to sample a grasp pose for the tool again, now that we've found it
result = primitives.call(name='submit_capx_action', action='sample_grasp_pose', native_api=True, parameters={'object_name': 'tool'})
if result.ok:
    print(f"Grasp pose for tool: {result.output}")
else:
    print(f"Failed to sample grasp pose: {result}")

# Also get the current object pose to confirm location
result = primitives.call(name='submit_capx_action', action='get_object_pose', native_api=True, parameters={'object_name': 'tool'})
if result.ok:
    print(f"Tool pose: {result.output}")
else:
    print(f"Failed to get tool pose: {result}")
